 * Path text shared by error messages and the `keys` output: object keys are
 * joined with `.` and array indices are appended as `[i]`, both counted from
 * the document root.
 */

export function appendKey(path, key) {
  return path === '' ? key : `${path}.${key}`
}

export function appendIndex(path, index) {
  return `${path}[${index}]`
}
"}

