    if (child.headerClosed) fail(`table ${finalPath} is defined twice`)
    child.headerClosed = true
    return { node: child, path: finalPath }
  }
  if (child === undefined) {
    child = { kind: 'array-of-tables', items: [] }
    current.map.set(lastSeg, child)
  }
  if (child.kind !== 'array-of-tables') fail(`${finalPath} is not an array of tables`)
  const table = makeTableNode()
  child.items.push(table)
  return { node: table, path: finalPath }
}

function parseHeaderLine(scanner) {
  scanner.pos++ // consume '['
  let isArray = false
  if (scanner.peek() === '[') {
    isArray = true
    scanner.pos++
  }
  const segments = parseDottedName(scanner)
  scanner.skipWs()
  if (isArray) {
    if (scanner.peek() !== ']' || scanner.line[scanner.pos + 1] !== ']') fail('unterminated table header')
    scanner.pos += 2
  } else {
    if (scanner.peek() !== ']') fail('unterminated table header')
    scanner.pos += 1
  }
  scanner.consumeCommentIfAny()
  if (!scanner.atEnd()) fail('trailing text after a table header')
  return { segments, isArray }
}

function parseAssignmentSegments(scanner) {
  const segments = parseDottedName(scanner)
  scanner.skipWs()
  if (scanner.peek() !== '=') fail('expected key = value')
  scanner.pos++
  return segments
}

function firstSignificantIndex(line) {
  let i = 0
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  return i
}

export function buildDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTableNode()
  let current = { node: root, path: '' }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const idx = firstSignificantIndex(line)
    if (idx >= line.length) continue
    if (line[idx] === '#' || line[idx] === ';') continue

    const scanner = new Scanner(line)
    scanner.pos = idx

    try {
      if (scanner.peek() === '[') {
        const { segments, isArray } = parseHeaderLine(scanner)
        current = processHeader(root, segments, isArray)
      } else {
        const segments = parseAssignmentSegments(scanner)
        const { targetMap, lastSeg, finalPath } = beginAssign(current.node, segments, current.path)
        const value = parseValue(scanner, finalPath)
        scanner.consumeCommentIfAny()
        if (!scanner.atEnd()) fail('trailing text after a value')
        commitAssign(targetMap, lastSeg, finalPath, value)
      }
    } catch (e) {
      if (e && typeof e.reason === 'string') {
        const err = new Error(`line ${lineNo}: ${e.reason}`)
        err.isDocumentError = true
        throw err
      }
      throw e
    }
  }

  return root
}
"}

