{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-5SrKFn/src/parser.js","content":"/**
 * Parses election input text (the `candidates` and `ballot` directive
 * language read from standard input) into a structured election.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Raised for any malformed election input; carries the final CLI message. */
export class ParseError extends Error {}

/**
 * Parses election text into `{ candidates, ballots }`, where `candidates`
 * is the declared names in order and `ballots` is a list of
 * `{ count, ranking }` entries. Throws `ParseError` on the first invalid
 * line, per the input language described in the task.
 */
export function parseElection(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const parts = trimmed.split(/\s+/)
    const directive = parts[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new ParseError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      const names = parts.slice(1)
      if (names.length === 0) {
        throw new ParseError(`line ${lineNumber}: expected candidates <name>...`)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`line ${lineNumber}: invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`line ${lineNumber}: candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new ParseError(`line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (parts.length < 3) {
        throw new ParseError(`line ${lineNumber}: expected ballot <count> <candidate>...`)
      }
      const countStr = parts[1]
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError(`line ${lineNumber}: count must be a positive integer`)
      }
      const count = Number(countStr)
      const ranking = parts.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`line ${lineNumber}: unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(`line ${lineNumber}: candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, ranking })
    } else {
      throw new ParseError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

