/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parser.js'
import { runElection } from './election.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatRound(round) {
  const entries = [...round.counts.entries()].sort(([nameA, countA], [nameB, countB]) => {
    if (countA !== countB) return countB - countA
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  const fields = entries.map(([name, count]) => `${name}=${count}`)
  return `round ${round.number}: ${fields.join(' ')} exhausted=${round.exhausted}`
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) fail(err.message)
    throw err
  }

  const rounds = runElection(election.candidates, election.ballots)
  const lines = []

  if (mode === 'rounds') {
    for (const round of rounds) {
      lines.push(formatRound(round))
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    }
  } else {
    lines.push(`rounds ${rounds.length}`)
  }

  const winner = rounds[rounds.length - 1].winner
  lines.push(winner !== null ? `winner ${winner}` : 'no winner')

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

