  let total = 0

  for (const [name, info] of schedule) {
    if (!byDepth.has(info.depth)) byDepth.set(info.depth, [])
    byDepth.get(info.depth).push(name)
    maxDepth = Math.max(maxDepth, info.depth)
    total = Math.max(total, info.finish)
  }

  let out = ''
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (byDepth.get(depth) ?? []).sort()
    out += `wave ${depth}: ${names.join(' ')}\n`
  }
  out += `total ${total}\n`
  return out
}

