  let makespan = 0
  for (let i = 0; i < workers.length; i++) {
    const entries = workers[i].map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    out += `worker ${i}:${entries}\n`
    for (const run of workers[i]) makespan = Math.max(makespan, run.finish)
  }
  out += `makespan ${makespan}\n`
  return out
