{"file_path":"src/parser.js","content":"/**
 * Parses the plain-text election format described in the task: a
 * `candidates` line naming the field, followed by any number of `ballot`
 * lines. Throws an `Error` whose `message` is already formatted the way the
 * CLI reports it (either `line N: ...` or, for a missing `candidates` line,
 * a bare message with no line number).
 */

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

function fail(line, message) {
  return new Error(line === null ? message : `line ${line}: ${message}`)
}

export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  let candidatesDeclared = false
  let candidateNames = []
  let candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw fail(lineNumber, 'expected candidates <name>...')
      }
      const names = tokens.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw fail(lineNumber, `invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw fail(lineNumber, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidateNames = names
      candidateSet = seen
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw fail(lineNumber, 'expected ballot <count> <candidate>...')
      }
      const countText = tokens[1]
      if (!COUNT_PATTERN.test(countText)) {
        throw fail(lineNumber, 'count must be a positive integer')
      }
      const count = Number(countText)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw fail(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw fail(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw fail(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (!candidatesDeclared) {
    throw fail(null, 'no candidates')
  }

  return { candidates: candidateNames, ballots }
}
"}

