{"file_path":"src/format.js","content":"/**
 * Renders the counted election as the lines the CLI prints, one round per
 * line (plus an `eliminated` line where applicable) for `rounds` mode, or a
 * single round count for `tally` mode. Neither includes the trailing
 * `winner <name>` / `no winner` line; the caller appends that.
 */

function formatRound(roundNumber, counts, exhausted) {
  const entries = [...counts.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => votesB - votesA || (nameA < nameB ? -1 : nameA > nameB ? 1 : 0))
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

export function formatOutcomeLine(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

export function formatRoundsMode(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
    lines.push(formatRound(index + 1, round.counts, round.exhausted))
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(formatOutcomeLine(result.winner))
  return lines
}

export function formatTallyMode(result) {
  return [`rounds ${result.rounds.length}`, formatOutcomeLine(result.winner)]
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection } from './parser.js'
import { countElection } from './count.js'
import { formatRoundsMode, formatTallyMode } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
  fail('usage: cli.js rounds|tally')
}

const input = readFileSync(0, 'utf8')

let election
try {
  election = parseElection(input)
} catch (err) {
  fail(err.message)
}

const result = countElection(election.candidates, election.ballots)
const lines = mode === 'rounds' ? formatRoundsMode(result) : formatTallyMode(result)
process.stdout.write(lines.join('\n') + '\n')
"}

