  let scheme, authority, path, query

  if (ref.scheme !== undefined) {
    scheme = ref.scheme
    authority = ref.authority
    path = ref.path
    query = ref.query
  } else if (ref.authority !== undefined) {
    scheme = base.scheme
    authority = ref.authority
    path = ref.path
    query = ref.query
  } else if (ref.path === '') {
    scheme = base.scheme
    authority = base.authority
    path = base.path
    query = ref.query !== undefined ? ref.query : base.query
  } else {
    scheme = base.scheme
    authority = base.authority
    path = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
    query = ref.query
  }

  return { scheme, authority, path, query, fragment: ref.fragment }
}

/** Reassemble a parsed URI reference into its string form. */
export function serialize(parsed) {
  let out = ''
  if (parsed.scheme !== undefined) out += parsed.scheme + ':'
  if (parsed.authority !== undefined) out += '//' + parsed.authority
  out += parsed.path
  if (parsed.query !== undefined) out += '?' + parsed.query
  if (parsed.fragment !== undefined) out += '#' + parsed.fragment
  return out
}

/** Normalize one `normalize`-mode record. */
export function normalizeRecord(line) {
  return serialize(normalizeParsed(parseUriReference(line)))
}

/** Resolve and normalize one `resolve`-mode record: a base, a space, and a reference. */
export function resolveRecord(line) {
  const spaceIdx = line.indexOf(' ')
  if (spaceIdx === -1) {
    throw new LineError('expected a base and a reference')
  }
  const base = parseUriReference(line.slice(0, spaceIdx))
  if (base.scheme === undefined) {
    throw new LineError('the base has no scheme')
  }
  const ref = parseUriReference(line.slice(spaceIdx + 1))
  return serialize(normalizeParsed(resolveParsed(base, ref)))
}
"}

