const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

export { FormulaSyntaxError, KNOWN_FUNCTIONS }

/** Parse a formula body into an AST. Throws FormulaSyntaxError when invalid. */
export function parseFormula(body) {
  const tokens = lex(body)
  const state = { tokens, pos: 0 }
  const node = parseComparison(state)
  if (state.pos !== tokens.length) {
    throw new FormulaSyntaxError('trailing tokens')
  }
  return node
}

function peek(state) {
  return state.tokens[state.pos]
}

function expectOp(state, value) {
  const tok = peek(state)
  if (tok && tok.type === 'OP' && tok.value === value) {
    state.pos++
    return true
  }
  return false
}

function parseComparison(state) {
  let left = parseAdditive(state)
  for (;;) {
    const tok = peek(state)
    if (tok && tok.type === 'OP' && COMPARISON_OPS.has(tok.value)) {
      state.pos++
      const right = parseAdditive(state)
      left = { type: 'compare', op: tok.value, left, right }
    } else {
      break
    }
  }
  return left
}

function parseAdditive(state) {
  let left = parseMultiplicative(state)
  for (;;) {
    if (expectOp(state, '+')) {
      left = { type: 'binary', op: '+', left, right: parseMultiplicative(state) }
    } else if (expectOp(state, '-')) {
      left = { type: 'binary', op: '-', left, right: parseMultiplicative(state) }
    } else {
      break
    }
  }
  return left
}

function parseMultiplicative(state) {
  let left = parsePower(state)
  for (;;) {
    if (expectOp(state, '*')) {
      left = { type: 'binary', op: '*', left, right: parsePower(state) }
    } else if (expectOp(state, '/')) {
      left = { type: 'binary', op: '/', left, right: parsePower(state) }
    } else {
      break
    }
  }
  return left
}

function parsePower(state) {
  const left = parseUnary(state)
  if (expectOp(state, '^')) {
    const right = parsePower(state)
    return { type: 'binary', op: '^', left, right }
  }
  return left
}

