  if (expectOp(state, '-')) {
    return { type: 'unary', op: '-', operand: parseUnary(state) }
  }
  if (expectOp(state, '+')) {
    return { type: 'unary', op: '+', operand: parseUnary(state) }
  }
  return parsePrimary(state)
}

