 * The value model: a number, text, a boolean, or an error, plus the
 * arithmetic and comparison rules that combine them.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function num(value) {
  return { type: 'number', value }
}
export function text(value) {
  return { type: 'text', value }
}
export function bool(value) {
  return { type: 'bool', value }
}
export function err(token) {
  return { type: 'error', value: token }
}

/**
 * The value a numeric operator sees for one operand: an upstream error wins
 * outright, and text in an arithmetic position is `#VALUE!`. Returns null
 * when the operand is usable and gives its plain JavaScript number instead.
 */
export function arithError(v) {
  if (v.type === 'error') return v
  if (v.type === 'text') return err('#VALUE!')
  return null
}

export function toPlainNumber(v) {
  if (v.type === 'number') return v.value
  if (v.type === 'bool') return v.value ? 1 : 0
  throw new Error('toPlainNumber called on a non-numeric value')
}

/** Wrap a finite arithmetic result as a number, or `#DIV/0!` when it is not finite. */
export function finite(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

/** Compare two non-error values per the cross-kind ordering rules. Returns -1, 0 or 1. */
export function compareValues(l, r) {
  const rl = rank(l)
  const rr = rank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.type === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  const lb = l.value ? 1 : 0
  const rb = r.value ? 1 : 0
  return lb - rb
}
"}

