{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-xOuCRx/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parseRef, normalizeComponents, serialize, resolveRef } from './uri.js'

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function normalizeLine(record) {
  return serialize(normalizeComponents(parseRef(record)))
}

function resolveLine(record) {
  const spaceIndex = record.indexOf(' ')
  if (spaceIndex === -1) throw new Error('expected a base and a reference')
  const baseComponents = parseRef(record.slice(0, spaceIndex))
  if (baseComponents.scheme === null) throw new Error('the base has no scheme')
  const refComponents = parseRef(record.slice(spaceIndex + 1))
  return serialize(normalizeComponents(resolveRef(baseComponents, refComponents)))
}

function main() {
  const mode = process.argv[2]
  if ((mode !== 'normalize' && mode !== 'resolve') || process.argv.length !== 3) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const process_ = mode === 'normalize' ? normalizeLine : resolveLine

  const outputs = []
  for (let i = 0; i < records.length; i++) {
    try {
      outputs.push(process_(records[i]))
    } catch (err) {
      process.stderr.write(`error: line ${i + 1}: ${err.message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(outputs.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

